"""Read-only aggregate stock-pairs browser/manifest builder and closed-study audit."""
from pathlib import Path
from datetime import datetime,timezone
import argparse
import hashlib
import json
import sys
sys.path.insert(0,str(Path(__file__).resolve().parents[1]))
from research.pairs_study import STUDY,CASES,audit_records,decode_fragments
ROOT=Path('.local')/STUDY
OUT=Path('.local/performance')/STUDY
PLAN=Path('research/plans')/(STUDY+'.json')
FINANCIAL=['pairs','pairhold','spy']


def build():
    OUT.mkdir(parents=True,exist_ok=True)
    plan=json.loads(PLAN.read_text());budget=json.loads((ROOT/'budget.json').read_text());results={};audits={};probe=None
    for c in CASES:
        path=ROOT/(c+'-summary.json')
        if not path.exists():continue
        rows=json.loads(path.read_text())
        if c=='probe':probe=rows[0]
        else:results[c]=rows
        try:audits[c]=audit_records(rows,c)
        except ValueError as error:audits[c]=dict(passed=False,error=str(error))
    complete=set(results)==set(FINANCIAL) and probe is not None
    full=lambda c:next(x for x in results[c] if x['kind']=='full')
    action_parity=complete and len({json.dumps([a['split_counts'],a['dividend_counts']],sort_keys=True) for a in [probe,*[full(c)['audit'] for c in results]]})==1
    eligible=complete and action_parity and all(a.get('passed') for a in audits.values()) and len({a['fit_hash'] for a in audits.values() if a.get('passed')})==1 and len({full(c)['audit']['calendar_hash'] for c in results})==1 and len({full(c)['audit']['minute_observations'] for c in results})==1
    decision=None
    if eligible:
        a,b=full('pairs')['metrics'],full('spy')['metrics']
        growth=dict(cagr_beats_spy=a['cagr']>b['cagr'],calmar_at_least_spy=a['calmar'] is not None and a['calmar']>=b['calmar'],longest_uw_no_worse=a['longest_uw']<=b['longest_uw'])
        risk=dict(positive_cagr=a['cagr']>0,sharpe_at_least_spy=a['sharpe'] is not None and a['sharpe']>=b['sharpe'],shallower_dd=abs(a['dd'])<abs(b['dd']),longest_uw_no_worse=a['longest_uw']<=b['longest_uw'])
        decision=dict(growth_checks=growth,risk_checks=risk,growth_pass=all(growth.values()),risk_alternative_pass=all(risk.values()),calmar_excess=a['calmar']-b['calmar'] if a['calmar'] is not None else None,cagr_excess=a['cagr']-b['cagr'],positive_cagr_condition=a['cagr']>0,drawdown_reassessment=max(abs(a['dd']),abs(full('pairs')['audit']['minute_dd']))>.3,status='retain-for-independent-validation-only' if all(growth.values()) or all(risk.values()) else 'stop-fixed-adaptation-no-improvement-screen-passed')
    report=dict(study=STUDY,generated_utc=datetime.now(timezone.utc).isoformat(),eligible=eligible,complete=complete,action_parity=action_parity,results=results,probe=probe,audits=audits,decision=decision,plan=plan,budget=budget)
    (OUT/'review.json').write_text(json.dumps(report,indent=2)+'\n')
    (OUT/'index.html').write_text(PAGE.replace('__DATA__',json.dumps(report,separators=(',',':')).replace('<','\\u003c')))
    files=[PLAN,Path(__file__),Path('tests/test_pairs_study.py')]+[Path(f) for f in plan['input_hashes']]+[p for p in ROOT.rglob('*') if p.is_file()]+[OUT/'review.json',OUT/'index.html']
    files +=[p for p in [OUT/'browser-audit.json',OUT/'review-preview.png'] if p.exists()]
    manifest=dict(study=STUDY,eligible=eligible,files=[dict(path=str(p),bytes=p.stat().st_size,sha256=hashlib.sha256(p.read_bytes()).hexdigest()) for p in sorted(set(files))])
    (OUT/'manifest.json').write_text(json.dumps(manifest,indent=2)+'\n')
    print(json.dumps(dict(eligible=eligible,cases=list(results),decision=decision,manifest_files=len(manifest['files']))))


def audit():
    manifest=json.loads((OUT/'manifest.json').read_text());r=json.loads((OUT/'review.json').read_text());p,b=r['plan'],r['budget']
    for f in manifest['files']:
        data=Path(f['path']).read_bytes()
        if len(data)!=f['bytes'] or hashlib.sha256(data).hexdigest()!=f['sha256']:raise ValueError('Manifest drift:'+f['path'])
    if b['status']!='closed' or len(b['attempts'])>6 or any(x['status']=='reserved' for x in b['attempts']):raise ValueError('Open/excessive budget')
    if sum(max(0,sum(x['case']==c for x in b['attempts'])-1) for c in CASES)>2:raise ValueError('Retry limit')
    for a in b['attempts']:
        if not datetime.fromisoformat(p['created_utc'])<=datetime.fromisoformat(a['reserved_utc'])<=datetime.fromisoformat(p['deadline_utc']):raise ValueError('Reservation time')
    for f,d in p['input_hashes'].items():
        if hashlib.sha256(Path(f).read_bytes()).hexdigest()!=d:raise ValueError('Frozen input drift')
    for old in p['negative_baselines']:
        if hashlib.sha256(Path(old['manifest_path']).read_bytes()).hexdigest()!=old['manifest_sha256']:raise ValueError('Negative baseline changed')
    if not r['eligible']:raise ValueError('Comparison ineligible')
    browser=json.loads((OUT/'browser-audit.json').read_text())
    chart_counts={key:sum(row['kind']=='annual' and row['metrics'][key] is not None for rows in r['results'].values() for row in rows) for key in ['ret','dd','sharpe','annual_calmar','uw_fraction','longest_uw','longest_uw_days']}
    if not browser['passed'] or not browser['all_table_cells_verified'] or browser['annual_rows']!=30 or len(browser['charts'])!=7 or any(not x['passed'] or x['points']!=chart_counts[x['metric']] for x in browser['charts']) or browser['decision']!=r['decision']:raise ValueError('Browser check missing/stale')
    for c in CASES:
        attempts=[a for a in b['attempts'] if a['case']==c and a['status']=='completed']
        if len(attempts)!=1 or attempts[0]['source_sha256']!=p['source_hashes'][c]:raise ValueError('Actual attempt/source')
        rows=decode_fragments(json.loads((ROOT/(c+'-fragments.json')).read_text()),c);audit_records(rows,c)
        if c!='probe' and rows!=r['results'][c]:raise ValueError('Packet/report mismatch')
        status=(ROOT/(c+'-visible-status.txt')).read_text();proof=json.loads((ROOT/(c+'-editor-verification.json')).read_text())
        if not proof['saved_and_reloaded_equal'] or proof['source_sha256']!=p['source_hashes'][c] or 'v2.5.0.0.18209' not in status or 'PRS_START|'+c+'|' not in status or 'Algorithm Id:('+attempts[0]['backtest_id']+') completed' not in status or 'Runtime Error' in status:raise ValueError('Hosted identity/completion')
    print(json.dumps(dict(passed=True,financial_cases=3,input_probe=1,annual_rows=30,attempts=len(b['attempts']),manifest_files=len(manifest['files']))))


PAGE='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Stock pairs · causal comparison</title><style>
:root{color-scheme:light;--ink:#203730;--line:#d4dbd0;--muted:#596c63}*{box-sizing:border-box}body{margin:0;background:#f3f1eb;color:var(--ink);font:15px/1.5 system-ui}main{max-width:1370px;margin:32px auto;padding:0 24px}h1{font-size:36px;line-height:1.15;max-width:1000px;letter-spacing:-1px;margin:10px 0 20px}h2{font-size:23px;margin:30px 0 12px}.eyebrow{font-size:12px;letter-spacing:2px;text-transform:uppercase}.note,footer{color:var(--muted)}.badge{background:#dfebdc;padding:6px 12px;border-radius:20px;display:inline-block}.warn{background:#f1ddca}.flow{background:#e4ebe1;border-left:3px solid #1b7062;padding:14px;margin:20px 0}.card,details{background:#fffdf7;padding:18px;border:1px solid var(--line);border-radius:10px;margin:12px 0}summary{cursor:pointer;font-weight:600}.scroll{overflow:auto;border:1px solid var(--line);border-radius:10px;margin:14px 0}table{background:#fffdf7;width:100%;border-collapse:collapse;font-size:13px}th,td{padding:10px;text-align:right;border-bottom:1px solid var(--line);white-space:nowrap}th:first-child,td:first-child{text-align:left}th{background:#e4eade}select{padding:8px;font:inherit;background:#fffdf7;border:1px solid var(--line);border-radius:6px}label{margin:8px 8px 8px 0;display:inline-block}.legend{display:flex;gap:20px;flex-wrap:wrap;font-size:13px}.legend span:before{content:'● ';color:var(--c)}svg{width:100%;height:300px}a{color:#196b61}footer{font-size:12px;margin:30px 0}@media(max-width:700px){h1{font-size:29px}main{padding:0 16px}}
</style><main><div class="eyebrow">Quant Trading Lab · causal NVDA / AMD pairs · 2016–2025</div><h1>Can relative-value mean reversion improve on holding SPY?</h1><div id="status" class="badge"></div><p class="note">$300,000 simulated capital · 98% gross targets · native IB fees + 5bp/fill · cash dividends and splits included · 6% cash debit / 3% short borrow. Three fixed financial cases after an order-free input probe. The stock-hold control uses a hindsight-selected pair; it does not validate stock selection.</p><div class="flow">Licensed example → timing / statistics / sizing repair → free-data gate → fresh controls and pair → accounting + temporal audit</div><h2>Full-period results</h2><div class="scroll"><table id="full"></table></div><div id="decision" class="card"></div><h2>Year by year</h2><label for="metric">Chart metric</label><select id="metric"><option value="ret">Annual return</option><option value="dd">Annual max drawdown</option><option value="sharpe">Annual Sharpe</option><option value="annual_calmar">Annual Calmar</option><option value="uw_fraction">Time underwater</option><option value="longest_uw">Longest underwater, sessions</option><option value="longest_uw_days">Longest underwater, calendar days</option></select><div class="legend"><span style="--c:#196b61">Causal pairs</span><span style="--c:#697eab">NVDA / AMD hold</span><span style="--c:#bd673b">SPY hold</span></div><p class="note">Annual peaks reset; full-period drawdown and underwater duration carry earlier losses across years. Undefined ratios appear as — in tables and gaps in charts, never zero.</p><div id="chart" class="card"></div><div class="scroll"><table id="annual"></table></div><h2>Execution, exposure and corporate actions</h2><div class="scroll"><table id="execution"></table></div><h2>Data readiness and fit integrity</h2><div id="probe" class="card"></div><div class="scroll"><table id="cohorts"></table></div><details open><summary>Qualification and trial history</summary><div id="audit"></div><p><a href="review.json">Aggregate evidence</a> · <a href="manifest.json">Artifact manifest</a> · <a href="https://www.quantconnect.com/project/38514439">Hosted project</a></p></details><details><summary>Source, causal repairs and definitions</summary><p>The pinned je-suis-tm/quant-trading stock-pairs script is Apache-2.0. Original full-sample maximum-price sizing is future aware; ordinary residual ADF p-values, mixed-unit bands and row-reset holding state also require repairs. This is a declared NVDA/AMD mechanism adaptation, not exact tutorial or original2013–2014 reproduction. The original is never imported/executed.</p><p>Fit AMD on NVDA+constant using250strictly prior aligned daily closes, SCALED_RAW normalized with actions known at current decision time. Score current closing residual using prior sample mean/SD. Require cointegration-specific p&lt;.05 (constant,maxlag5,AIC), positive beta and negative error-correction coefficient. Enter at dimensionless z±1; persist until zero crossing or gate failure. Hedge gross98%, refit/rebalance daily; execute queued weights next session9:32 on RAW bars. Pairhold buys49%each once; SPY98%once, same initial execution. No terminal liquidation.</p><p>Raw splits/dividend cash, including short debits, are native. Funding6%ACT/360 prior-close negativecash, zero credit, native interest off. Borrow3%ACT/365 previous-event shortnotional×elapsed seconds includes overnights/weekends; historical locates/availability/recalls and capacity are assumed or unmodeled. Target gross is not a hard realized cap. The pair is ex-post selected; long-pair holding is not exposure/beta matched. Native minimum-order guards may skip tiny rebalance recommendations; the observed warning is preserved and actual fills/exposure are reported.</p><p>Sharpe uses sample daily returns, zeroRF and√252. Full Calmar uses calendar-day CAGR/absolute closingDD; annual Calmar uses annual return/absoluteDD. Annual peaks reset; full peaks carry. Underwater calendar duration ends at last underwater close; open at end describes the terminal decline. Minute-mark DD/exposure add intraday diagnostics.</p><p>Viewed development history, rolling statistical tests and I(1) assumptions do not establish independent alpha. Native daily/lifetime book checks do not replace independent action/cash replay. CAPM and Dual Thrust remain separate negative baselines with different contexts. No parameter search, trained RL advantage, broker operation or promotion follows.</p><p><a href="https://github.com/je-suis-tm/quant-trading/blob/611b73f2c3f577ac5b28aaa19ac8c43d3236c7a5/Pair%20trading%20backtest.py">Pinned licensed example</a> · <a href="https://www.statsmodels.org/stable/generated/statsmodels.tsa.stattools.coint.html">Cointegration test</a> · <a href="https://www.quantconnect.com/docs/v2/writing-algorithms/securities/asset-classes/us-equity/requesting-data#08-Data-Normalization">Normalization timing</a></p></details><footer>Own aggregate results only. Raw market paths stay hosted. Failed attempts remain preserved; budgets do not roll over.</footer></main><script>
const D=__DATA__,cs=['pairs','pairhold','spy'],names={pairs:'Causal NVDA / AMD pairs',pairhold:'NVDA / AMD hold',spy:'SPY hold'},colors={pairs:'#196b61',pairhold:'#697eab',spy:'#bd673b'},el=id=>document.getElementById(id),pct=v=>v==null?'—':(100*v).toFixed(2)+'%',num=v=>v==null?'—':Number(v).toFixed(2),full=c=>D.results[c]?.find(r=>r.kind==='full'),annual=c=>D.results[c]?.filter(r=>r.kind==='annual').sort((a,b)=>a.year-b.year)||[];
function table(id,headers,rows){el(id).innerHTML='<thead><tr>'+headers.map(h=>`<th>${h}</th>`).join('')+'</tr></thead><tbody>'+rows.map(row=>'<tr>'+row.map(v=>`<td>${v}</td>`).join('')+'</tr>').join('')+'</tbody>'}
const done=cs.filter(c=>full(c));el('status').textContent=D.eligible?'Completed · all cases qualified':'Partial / qualification incomplete';if(!D.eligible)el('status').classList.add('warn');table('full',['Case','CAGR','Total return','Max DD','Sharpe','Calmar','Underwater','Longest sessions','Calendar days','Open at end'],done.map(c=>{let m=full(c).metrics;return [names[c],pct(m.cagr),pct(m.ret),pct(m.dd),num(m.sharpe),num(m.calmar),pct(m.uw_fraction),m.longest_uw,m.longest_uw_days,m.censored?'Yes':'No']}));table('annual',['Year / case','Return','Max DD','Sharpe','Calmar','Underwater','Longest sessions','Calendar days','Open at end'],Array.from({length:10},(_,i)=>2016+i).flatMap(y=>done.map(c=>{let m=annual(c).find(r=>r.year===y)?.metrics;return [y+' · '+names[c],pct(m.ret),pct(m.dd),num(m.sharpe),num(m.annual_calmar),pct(m.uw_fraction),m.longest_uw,m.longest_uw_days,m.censored?'Yes':'No']})));table('execution',['Case','Fills','Fees USD','Debit USD','Borrow USD','Native dividends USD','Mean gross','Mean net','Peak gross','Minute DD','Rejected','Daily book residual max'],done.map(c=>{let a=full(c).audit;return [names[c],a.fills,num(a.fees),num(a.interest),num(a.borrow_usd),num(a.native_dividends),num(a.minute_mean_gross)+'x',num(a.minute_mean_net)+'x',num(a.minute_max_gross)+'x',pct(a.minute_dd),a.rejects,num(a.daily_book_max)]}));table('cohorts',['Case','Ready days','Eligible days','Minute observations','Short minutes','NVDA splits','SPY dividends','Fit hash'],done.map(c=>{let a=full(c).audit;return [names[c],a.ready_days,a.eligible_days,a.minute_observations,a.short_minutes,a.split_counts.NVDA,a.dividend_counts.SPY,a.fit_hash]}));
function chart(){let key=el('metric').value,vals=done.flatMap(c=>annual(c).map(r=>r.metrics[key]).filter(v=>v!=null));if(!vals.length){el('chart').textContent='Waiting for qualified financial outputs';return}let lo=Math.min(0,...vals),hi=Math.max(0,...vals),pad=Math.max((hi-lo)*.08,.01);lo-=pad;hi+=pad;let y=v=>255-(v-lo)/(hi-lo)*220,body=`<line x1="55" x2="1150" y1="${y(0)}" y2="${y(0)}" stroke="#a5aea2"/>`;for(let j=0;j<5;j++){let v=lo+(hi-lo)*j/4;body+=`<text x="48" y="${y(v)+4}" text-anchor="end" font-size="11">${['ret','dd','uw_fraction'].includes(key)?pct(v):num(v)}</text>`}done.forEach(c=>{let rows=annual(c),segments=[[]];rows.forEach((r,i)=>{if(r.metrics[key]==null){segments.push([])}else segments.at(-1).push(`${75+i*117},${y(r.metrics[key])}`)});segments.filter(x=>x.length).forEach(segment=>{body+=`<polyline points="${segment.join(' ')}" fill="none" stroke="${colors[c]}" stroke-width="2"/>`});rows.forEach((r,i)=>{let v=r.metrics[key];if(v!=null)body+=`<circle cx="${75+i*117}" cy="${y(v)}" r="4" fill="${colors[c]}"><title>${r.year} ${names[c]}: ${v}</title></circle>`})});for(let i=0;i<10;i++)body+=`<text x="${75+i*117}" y="290" text-anchor="middle" font-size="12">${2016+i}</text>`;el('chart').innerHTML=`<svg viewBox="0 0 1160 300" role="img" aria-label="Annual metric comparison">${body}</svg>`}el('metric').addEventListener('change',chart);chart();let dec=D.decision;if(dec){el('decision').innerHTML=`<p><strong>${dec.growth_pass||dec.risk_alternative_pass?'Passes a frozen development screen; independent validation still required.':'Neither frozen improvement screen passes.'}</strong> Calmar excess versus SPY: ${num(dec.calmar_excess)}; positive-CAGR condition: ${dec.positive_cagr_condition?'pass':'fail'}. CAGR excess: ${num(dec.cagr_excess*100)}pp.</p><p>Growth screen: ${dec.growth_pass?'pass':'fail'} · Risk-alternative screen: ${dec.risk_alternative_pass?'pass':'fail'} · 30% DD reassessment reference: ${dec.drawdown_reassessment?'exceeded':'not exceeded in this viewed history'}.</p>`}else el('decision').textContent='Final interpretation waits for qualified outputs.';el('probe').textContent=D.probe?`Order-free input gate: ${D.audits.probe?.passed?'passed':'failed'}. ${D.probe.ready_days} ready sessions; ${D.probe.years.length} annual checkpoints; ${D.probe.fills} fills. statsmodels ${D.probe.statsmodels}; normalization ${D.probe.normalization.join(', ')}.`:'Input gate not yet qualified.';el('audit').innerHTML=`<p>${Object.keys(D.results).length}/3 financial cases exported. ${D.budget.attempts.length}/6 attempts; ${D.budget.status}. ${Object.entries(D.audits).map(([c,a])=>c+': '+(a.passed?'passed':a.error)).join(' · ')}</p><p>All cases share fit, calendar and action checks. Raw prices and dense NAV remain hosted.</p><div class="scroll"><table><thead><tr><th>Attempt</th><th>Case</th><th>Status</th></tr></thead><tbody>${D.budget.attempts.map(a=>`<tr><td>${a.id}</td><td>${a.case}</td><td>${a.status}</td></tr>`).join('')}</tbody></table></div>`;
</script></html>'''


if __name__=='__main__':
    ap=argparse.ArgumentParser();ap.add_argument('--audit',action='store_true');args=ap.parse_args();audit() if args.audit else build()
